import { invoke } from "@tauri-apps/api/core";
import type { ProviderId } from "./models";

const API_BASE = "http://127.0.0.1:8765";

// ---------------------------------------------------------------------------
// Local API token
// ---------------------------------------------------------------------------
// The backend can run shell commands, so it refuses every request that does not
// carry the per-launch token generated by the Rust shell. `invoke` is the only
// way to read it; the WebView never writes it to storage and a new one is made
// on every start.
let apiTokenPromise: Promise<string> | null = null;

function getApiToken(): Promise<string> {
  if (!apiTokenPromise) {
    apiTokenPromise = invoke<string>("api_token").catch((err) => {
      // Let the next call retry (the shell may still be starting up).
      apiTokenPromise = null;
      throw err;
    });
  }
  return apiTokenPromise;
}

/** Merge the token into a header set. */
async function withToken(
  headers: Record<string, string> = {},
): Promise<Record<string, string>> {
  return { ...headers, "X-Jarvis-Token": await getApiToken() };
}

// ---------------------------------------------------------------------------
// Backend readiness
// ---------------------------------------------------------------------------
// The Python child needs a moment to bind port 8765. Calling the API before
// that only produces ERR_CONNECTION_REFUSED noise in devtools on every start.
// Every HTTP request waits here first; the shell reports the real failure if
// the backend could not start at all.

const READY_POLL_MS = 250;
// The Rust watchdog gives the backend 60s before reporting failure; wait a
// little longer so we surface its message instead of our own timeout.
const READY_TIMEOUT_MS = 65_000;

let backendReadyPromise: Promise<void> | null = null;

async function waitForBackend(): Promise<void> {
  if (!backendReadyPromise) {
    backendReadyPromise = (async () => {
      const deadline = Date.now() + READY_TIMEOUT_MS;
      while (Date.now() <= deadline) {
        let status: BackendStatus | null = null;
        let shellAvailable = false;
        try {
          status = await invoke<BackendStatus>("backend_status");
          shellAvailable = true;
        } catch {
          // Not running inside Tauri (plain browser dev): probe /health below.
          shellAvailable = false;
        }
        if (status?.ready) return;
        if (status?.failed) {
          throw new Error(status.message || "Jarvis backend failed to start");
        }
        if (!shellAvailable) {
          try {
            // /health is deliberately token-free, so this works before the
            // token is available too.
            const res = await fetch(`${API_BASE}/health`);
            if (res.ok) return;
          } catch {
            // Backend is still starting up.
          }
        }
        await new Promise((r) => setTimeout(r, READY_POLL_MS));
      }
      throw new Error("Jarvis backend did not start in time");
    })().catch((err) => {
      // Let the next request retry instead of caching a transient failure.
      backendReadyPromise = null;
      throw err;
    });
  }
  return backendReadyPromise;
}

// ============================================================================
// Типы: AppConfig (хранится в Tauri: провайдеры → ключи, выбранная primary)
// ============================================================================

/** Silero is the only TTS engine; the saved config still records it explicitly. */
export interface TTSConfig {
  provider: "silero";
  enabled: boolean;
  model_id: string;
  speaker: string;
  language: string;
  sample_rate: number;
  device: string;
}

export const DEFAULT_TTS_CONFIG: TTSConfig = {
  provider: "silero",
  enabled: true,
  model_id: "v4_ru",
  speaker: "aidar",
  language: "ru",
  sample_rate: 48000,
  device: "cpu",
};

export function normalizeTTSConfig(raw: any): TTSConfig {
  const src = raw && typeof raw === "object" ? raw : {};
  return {
    provider: "silero",
    enabled: typeof src.enabled === "boolean" ? src.enabled : DEFAULT_TTS_CONFIG.enabled,
    model_id: typeof src.model_id === "string" ? src.model_id : DEFAULT_TTS_CONFIG.model_id,
    speaker: typeof src.speaker === "string" ? src.speaker : DEFAULT_TTS_CONFIG.speaker,
    language: typeof src.language === "string" ? src.language : DEFAULT_TTS_CONFIG.language,
    sample_rate: Number.isFinite(src.sample_rate)
      ? Number(src.sample_rate)
      : DEFAULT_TTS_CONFIG.sample_rate,
    device: typeof src.device === "string" ? src.device : DEFAULT_TTS_CONFIG.device,
  };
}

/** Конфиг, совместимый с Rust AppConfig: api_keys — HashMap<String, String>, selected_model тоже обязательно */
export interface AppConfig {
  api_keys: Record<string, string>;
  selected_primary: { provider: ProviderId; model: string } | null;
  selected_model: Record<string, string>;
  /** Code-agent tools the user switched off in the side dock. */
  disabled_tools: string[];
  /** Local Silero voice used only by main-agent voice mode. */
  tts: TTSConfig;
}

export async function getConfig(): Promise<AppConfig> {
  const raw = await invoke<any>("get_config");
  return normalizeConfig(raw);
}

export async function setConfig(config: AppConfig): Promise<void> {
  await invoke("set_config", { newConfig: config });
}

/**
 * Нормализует конфиг из любого старого формата.
 * - Старый selected_model Record<string, string> → selected_primary {provider,model}
 * - Старые ключи строкой → Record<string, string>
 */
export function normalizeConfig(raw: any): AppConfig {
  if (!raw) raw = {};
  const api_keys: Record<string, string> = {};
  const srcKeys = raw.api_keys ?? {};
  for (const [k, v] of Object.entries<any>(srcKeys)) {
    if (typeof v === "string") api_keys[k] = v;
    else if (v && typeof v === "object" && typeof v.key === "string") api_keys[k] = v.key;
  }

  let selected_primary: AppConfig["selected_primary"] = null;

  if (raw.selected_primary && typeof raw.selected_primary === "object") {
    selected_primary = {
      provider: raw.selected_primary.provider as ProviderId,
      model: String(raw.selected_primary.model ?? ""),
    };
  }

  // Legacy fallback — selected_model: { provider, code }
  if (!selected_primary && raw.selected_model && typeof raw.selected_model === "object") {
    const sm = raw.selected_model as Record<string, string>;
    if (sm.provider && sm.code) {
      selected_primary = { provider: sm.provider as ProviderId, model: sm.code };
    }
  }

  const disabled_tools = Array.isArray(raw.disabled_tools)
    ? raw.disabled_tools.filter((n: any) => typeof n === "string")
    : [];

  return {
    api_keys,
    selected_primary,
    selected_model: raw.selected_model || {},
    disabled_tools,
    tts: normalizeTTSConfig(raw.tts),
  };
}

// ============================================================================
// Типы: ChatRequest Body (новый контракт с primary_spec)
// ============================================================================

export interface ModelSpec {
  provider: ProviderId;
  model: string;
}

export interface ChatRequestPayload {
  message: string;
  /** Explicit agent choice. The backend never overrides it from message text. */
  agent_type?: "main" | "code";
  /** Explicit UI signal to speak the main-agent reply with Silero TTS. */
  synthesize_speech?: boolean;
  /** Stable id so the backend can keep this conversation's history across turns. */
  conversation_id?: string;
  primary_spec?: ModelSpec;
  /** Legacy-поля — для обратной совместимости, слой сервера их всё равно читает */
  primary_model?: string;
  primary_provider?: ProviderId;
  /** Ключи: { groq: {key: "..."}, google: {key: "..."}, ... } или { groq: "...", ... } */
  api_keys?: Record<string, string>;
  api_key?: string;
  system_prompt?: string;
  vision_model?: string;
  config?: any;
  /** Code-agent tools to hide from the model for this request. */
  disabled_tools?: string[];
  /** Attached files (images, documents, archives) — absolute paths on the server. */
  attachments?: FileAttachment[];
}

/** File uploaded by the user and persisted by the backend. */
export interface FileAttachment {
  /** Absolute path on the server where the file was saved. */
  path: string;
  /** Original file name. */
  name: string;
  /** MIME type, e.g. "image/png", "text/plain". */
  mime?: string;
  /** File size in bytes. */
  size?: number;
  /** For images: local preview URL (blob: URL) for frontend display only. */
  previewUrl?: string;
  /** For images: base64 data URL (optional, for inline display). */
  dataUrl?: string;
}

export interface ToolCallInfo {
  name: string;
  arguments: string;
}

export interface ChatResponse {
  reply: string | null;
  tool_calls: ToolCallInfo[] | null;
  audio: string | null;
  /** Images returned by the model (Vision responses), as base64 data URLs. */
  images?: string[];
}

export interface HealthResponse {
  status: string;
  service?: string;
  data_dir?: string;
  workspace?: string;
}

/**
 * Backend state tracked by the Tauri shell. A packaged app starts the Python
 * child itself, so only Rust knows why it failed (missing runtime, blocked by
 * antivirus, port taken) - the UI just renders this.
 */
export interface BackendStatus {
  /** /health answered 200. */
  ready: boolean;
  /** Startup failed, or the backend stopped answering. */
  failed: boolean;
  message: string;
  /** "dev" | "bundled" | "none" */
  mode: string;
}

// ============================================================================
// SSE Stream Events
// ============================================================================

export interface StreamProgressEvent {
  type: "progress";
  phase: string;
  label?: string;
  detail?: string;
  tool?: string;
  duration?: number;
  status?: string;
  reason?: string;
}
export interface StreamThoughtEvent {
  type: "thought";
  preview: string;
}
export interface StreamFinalEvent {
  type: "final";
  reply: string | null;
  audio: string | null;
  success: boolean;
  state: string;
  iterations: number;
  tool_calls: number;
  trace_id: string | null;
  model_used: string;
  attempts: number;
  verification_status: string | null;
  verification_reason: string | null;
  error: string | null;
  /** Echoed/assigned by the backend; persist it for the next turn. */
  conversation_id?: string | null;
}
export interface StreamPlanEvent {
  type: "plan";
  steps: { id: string; text: string; status: string }[];
}
export interface StreamReportEvent {
  type: "report";
  text: string;
}
export interface StreamPlanUpdatedEvent {
  type: "plan_updated";
  steps: { id: string; text: string; status: string }[] | null;
}
export interface StreamToolEvent {
  type: "tool_started" | "tool_completed";
  tool?: string;
  args?: any;
  status?: string;
  duration?: number;
  call_id?: string;
}
export interface StreamToolProgressEvent {
  type: "tool_progress";
  tool?: string;
  call_id?: string;
  /** Estimated completion, 0..100. `done` events carry exactly 100. */
  percent: number;
  nodes: number;
  bytes: number;
  queued: number;
  elapsed: number;
  done: boolean;
}
export interface StreamAgentMessageEvent {
  type: "agent_message";
  message: string;
}
export interface StreamStreamEvent {
  type: "stream";
  text: string;
  iteration?: number;
}
export interface StreamExecutionInfoEvent {
  type: "execution_error" | "execution_completed" | "task_started" | "task_completed" | "task_failed";
  message?: string;
  error?: string;
}
export interface StreamRateLimitEvent {
  type: "rate_limit";
  /** "waiting" | "fallback" | "exhausted" */
  phase: "waiting" | "fallback" | "exhausted";
  /** Current provider that hit the limit */
  provider: string;
  /** Fallback provider being tried (if phase="fallback") */
  fallback_provider?: string;
  /** Seconds to wait before retry */
  wait_seconds?: number;
  /** Human-readable message */
  message: string;
}
export interface StreamHandshakeEvent {
  type: "handshake";
  event_schema_version: number;
  timestamp: number;
}
export type StreamEvent =
  | StreamProgressEvent
  | StreamThoughtEvent
  | StreamPlanEvent
  | StreamReportEvent
  | StreamPlanUpdatedEvent
  | StreamToolEvent
  | StreamToolProgressEvent
  | StreamAgentMessageEvent
  | StreamStreamEvent
  | StreamExecutionInfoEvent
  | StreamRateLimitEvent
  | StreamHandshakeEvent
  | StreamFinalEvent;

// ============================================================================
// Отправка запросов (Voice Jarvis + Code Agent, streaming и обычные)
// ============================================================================

function buildBody(
  message: string,
  primary: ModelSpec | undefined | null,
  apiKeys: Record<string, string> | undefined,
  extra: Partial<ChatRequestPayload> = {},
): string {
  const payload: ChatRequestPayload = { message, ...extra };
  if (primary) payload.primary_spec = primary;
  if (apiKeys) payload.api_keys = apiKeys;
  return JSON.stringify(payload);
}

// --- Non-streaming ---------------------------------------------------------

/** Voice Jarvis POST /chat */
export async function sendVoiceChat(
  message: string,
  primary?: ModelSpec | null,
  apiKeys?: Record<string, string>,
): Promise<ChatResponse> {
  return apiFetch<ChatResponse>("/chat", {
    method: "POST",
    body: buildBody(message, primary, apiKeys, { agent_type: "main" }),
  });
}

/** Code Agent POST /code/chat */
export async function sendCodeChat(
  message: string,
  primary?: ModelSpec | null,
  apiKeys?: Record<string, string>,
): Promise<ChatResponse> {
  return apiFetch<ChatResponse>("/code/chat", {
    method: "POST",
    body: buildBody(message, primary, apiKeys, { agent_type: "code" }),
  });
}

// --- Streaming -------------------------------------------------------------

export async function sendChatStreaming(
  endpoint: "/chat/stream" | "/code/chat/stream" | "/agent/chat/stream",
  message: string,
  primary: ModelSpec | undefined | null,
  apiKeys: Record<string, string> | undefined,
  onEvent: (event: StreamEvent) => void,
  extra: Partial<ChatRequestPayload> = {},
  signal?: AbortSignal,
): Promise<StreamFinalEvent> {
  await waitForBackend();
  const res = await fetch(`${API_BASE}${endpoint}`, {
    method: "POST",
    headers: await withToken({
      "Content-Type": "application/json",
      Accept: "text/event-stream",
    }),
    body: buildBody(message, primary, apiKeys, extra),
    signal,
  });

  if (!res.ok || !res.body) {
    throw new Error(`API ${res.status}: ${res.statusText}`);
  }

  const reader = res.body.getReader();
  const decoder = new TextDecoder("utf-8");
  let buffer = "";
  let finalEvent: StreamFinalEvent | null = null;

  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });

    let sepIdx: number;
    while ((sepIdx = buffer.indexOf("\n\n")) >= 0) {
      const frame = buffer.slice(0, sepIdx);
      buffer = buffer.slice(sepIdx + 2);
      const lines = frame.split("\n");
      for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed.startsWith("data:")) continue;
        const payloadText = trimmed.slice(5).trim();
        if (!payloadText) continue;
        try {
          const ev = JSON.parse(payloadText) as StreamEvent;
          if (ev.type === "final") {
            finalEvent = ev;
          } else {
            onEvent(ev);
          }
        } catch {
          // ignore malformed frames
        }
      }
    }
  }

  if (!finalEvent) {
    throw new Error("Stream did not produce a final event");
  }
  return finalEvent;
}

/** Streaming Code Agent — /code/chat/stream */
export async function sendCodeChatStreaming(
  message: string,
  primary: ModelSpec | undefined | null,
  apiKeys: Record<string, string> | undefined,
  onEvent: (event: StreamEvent) => void,
  extra: Partial<ChatRequestPayload> = {},
  signal?: AbortSignal,
): Promise<StreamFinalEvent> {
  return sendChatStreaming(
    "/code/chat/stream",
    message,
    primary,
    apiKeys,
    onEvent,
    { ...extra, agent_type: "code" },
    signal,
  );
}

/** Streaming Main Jarvis — /chat/stream */
export async function sendMainChatStreaming(
  message: string,
  primary: ModelSpec | undefined | null,
  apiKeys: Record<string, string> | undefined,
  onEvent: (event: StreamEvent) => void,
  extra: Partial<ChatRequestPayload> = {},
  signal?: AbortSignal,
): Promise<StreamFinalEvent> {
  return sendChatStreaming(
    "/chat/stream",
    message,
    primary,
    apiKeys,
    onEvent,
    { ...extra, agent_type: "main" },
    signal,
  );
}

// ============================================================================
// Misc helpers
// ============================================================================

export async function healthCheck(): Promise<HealthResponse> {
  return apiFetch<HealthResponse>("/health");
}

/** Backend state as seen by Rust (works even when the API is unreachable). */
export async function getBackendStatus(): Promise<BackendStatus> {
  return invoke<BackendStatus>("backend_status");
}

export async function transcribeAudio(file: File): Promise<{ text: string }> {
  await waitForBackend();
  const form = new FormData();
  form.append("file", file);
  const res = await fetch(`${API_BASE}/stt/transcribe`, {
    method: "POST",
    headers: await withToken({}),
    body: form,
  });
  if (!res.ok) throw new Error(`STT ${res.status}: ${res.statusText}`);
  return res.json();
}

export function playAudioFromBase64(base64: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const audio = new Audio(`data:audio/wav;base64,${base64}`);
    audio.onended = () => resolve();
    audio.onerror = (e) => reject(e);
    audio.play().catch(reject);
  });
}

async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  await waitForBackend();
  const res = await fetch(`${API_BASE}${path}`, {
    ...init,
    headers: await withToken({
      "Content-Type": "application/json",
      ...((init?.headers as Record<string, string>) ?? {}),
    }),
  });
  if (!res.ok) throw new Error(`API ${res.status}: ${res.statusText}`);
  return res.json();
}

// ============================================================================
// File uploads (drag-drop / paste attachments)
// ============================================================================

/** Upload one or more files to the server. Returns server-side file info. */
export async function uploadFiles(
  files: FileList | File[],
): Promise<FileAttachment[]> {
  const fileArray = Array.from(files);
  const form = new FormData();
  for (const f of fileArray) {
    form.append("files", f);
  }
  await waitForBackend();
  const res = await fetch(`${API_BASE}/upload`, {
    method: "POST",
    headers: await withToken(),
    body: form,
  });
  if (!res.ok) {
    const text = await res.text().catch(() => res.statusText);
    throw new Error(`Upload failed (${res.status}): ${text}`);
  }
  const data = await res.json();
  return (data.attachments || []) as FileAttachment[];
}

// ============================================================================
// Tasks API
// ============================================================================

export interface TaskInfo {
  id: string;
  type: string;
  status: string;
  description: string;
  progress: number;
  eta: string;
  speed: string;
  result: string;
  error: string;
  created_at: number;
  updated_at: number;
}

export interface TaskEvent {
  event: string;
  task_id: string;
  progress?: number;
  eta?: string;
  speed?: string;
  result?: string;
  error?: string;
}

export async function fetchLiveModels(apiKeys?: Record<string, string>): Promise<Record<string, string[]>> {
  try {
    await waitForBackend();
    const res = await fetch(`${API_BASE}/models/fetch`, {
      method: "POST",
      headers: await withToken({ "Content-Type": "application/json" }),
      body: JSON.stringify({ api_keys: apiKeys }),
    });
    if (res.ok) {
      const data = await res.json();
      return data.models || {};
    }
  } catch (e) {
    console.error("Failed to fetch live models", e);
  }
  return {};
}

export interface CodeToolInfo {
  name: string;
  description: string;
  /** "always" = sent to the model upfront, "on_demand" = loaded via get_tools. */
  group: string;
}

/** GET /code/tools — full code-agent tool catalog for the side-dock toggles. */
export async function fetchCodeTools(retries = 3): Promise<CodeToolInfo[]> {
  await waitForBackend();
  for (let attempt = 0; attempt < retries; attempt++) {
    try {
      const res = await fetch(`${API_BASE}/code/tools`, {
        headers: await withToken(),
      });
      if (res.ok) {
        const data = await res.json();
        return (data.tools || []) as CodeToolInfo[];
      }
      if (res.status === 401) {
        // Token might be stale, invalidate and retry once
        apiTokenPromise = null;
        continue;
      }
    } catch (e) {
      console.error(`[fetchCodeTools] attempt ${attempt + 1}/${retries} failed:`, e);
    }
    if (attempt < retries - 1) await new Promise((r) => setTimeout(r, 500 * (attempt + 1)));
  }
  return [];
}

// ============================================================================
// Conversations (chat history)
// ============================================================================

export interface ConversationSummary {
  id: string;
  title: string;
  turns: number;
  updated: number;
}

/** One persisted event from the backend event log. */
export interface ConversationEvent {
  role?: string;
  content?: unknown;
  [k: string]: unknown;
}

/** GET /conversations — newest-first chat-history summaries. */
export async function fetchConversations(): Promise<ConversationSummary[]> {
  try {
    await waitForBackend();
    const res = await fetch(`${API_BASE}/conversations`, {
      headers: await withToken(),
    });
    if (res.ok) {
      const data = await res.json();
      return (data.conversations || []) as ConversationSummary[];
    }
  } catch (e) {
    console.error("Failed to fetch conversations", e);
  }
  return [];
}

/** GET /conversations/{id} — raw event log so the UI can replay it. */
export async function fetchConversation(id: string): Promise<ConversationEvent[]> {
  try {
    await waitForBackend();
    const res = await fetch(`${API_BASE}/conversations/${encodeURIComponent(id)}`, {
      headers: await withToken(),
    });
    if (res.ok) {
      const data = await res.json();
      return (data.events || []) as ConversationEvent[];
    }
  } catch (e) {
    console.error("Failed to fetch conversation", e);
  }
  return [];
}

export async function deleteConversation(id: string): Promise<boolean> {
  try {
    await waitForBackend();
    const res = await fetch(`${API_BASE}/conversations/${encodeURIComponent(id)}`, {
      method: "DELETE",
      headers: await withToken(),
    });
    return res.ok;
  } catch (e) {
    console.error("Failed to delete conversation", e);
  }
  return false;
}

export async function getTasks(): Promise<{ tasks: TaskInfo[]; active_count: number }> {
  return apiFetch("/tasks");
}

export async function getTask(taskId: string): Promise<TaskInfo> {
  return apiFetch(`/tasks/${taskId}`);
}

export async function cancelTask(taskId: string): Promise<void> {
  await apiFetch(`/tasks/${taskId}`, { method: "DELETE" });
}

export async function stopAgent(conversationId: string) {
  await waitForBackend();
  const res = await fetch(`${API_BASE}/agent/stop`, {
    method: "POST",
    headers: await withToken({ "Content-Type": "application/json" }),
    body: JSON.stringify({ conversation_id: conversationId }),
  });
  if (!res.ok) throw new Error(await res.text());
  return res.json();
}

// ============================================================================
// Streaming speech-to-text transport
// ============================================================================

/**
 * URL for the STT WebSocket. The token is passed in the query because the
 * WebSocket API cannot set headers; the endpoint validates it on upgrade.
 */
export async function sttStreamUrl(sessionId: string): Promise<string> {
  await waitForBackend();
  const token = await getApiToken();
  const query = `session_id=${encodeURIComponent(sessionId)}&token=${encodeURIComponent(token)}`;
  return `${API_BASE.replace(/^http/, "ws")}/stt/stream?${query}`;
}

export function subscribeTaskEvents(
  onEvent: (event: TaskEvent) => void,
): { stop: () => void } {
  // EventSource cannot set headers, so a GET may pass the token in the query.
  let source: EventSource | null = null;
  let stopped = false;

  getApiToken()
    .then(async (token) => {
      if (stopped) return;
      await waitForBackend();
      if (stopped) return;
      source = new EventSource(
        `${API_BASE}/tasks/events?token=${encodeURIComponent(token)}`,
      );
      source.onmessage = (e) => {
        try {
          const ev = JSON.parse(e.data);
          if (ev.type !== "ping") {
            onEvent(ev);
          }
        } catch {
          /* ignore */
        }
      };
    })
    .catch((err) => console.error("Failed to subscribe to task events", err));

  return {
    stop: () => {
      stopped = true;
      source?.close();
      source = null;
    },
  };
}
